// Generates src/icons/svgs.ts from Central Icons. Run with `npm run icons` after adding a name below.
// Needs the central-icon.mjs helper (prints one icon's SVG): ~/.claude/tools/central-icon.mjs, or set CENTRAL_ICON_TOOL.
// The generated file is committed, so building the page does not need it.
import { readFileSync, writeFileSync } from 'node:fs'
import { execFileSync } from 'node:child_process'
import { homedir } from 'node:os'
import { join } from 'node:path'
const tool = process.env.CENTRAL_ICON_TOOL ?? join(homedir(), '.claude/tools/central-icon.mjs')
const central = n => execFileSync('node', [tool, 'outlined', n], { encoding: 'utf8' }).trim()
const roundFilled = n => execFileSync('node', [tool, 'round-filled', n], { encoding: 'utf8' }).trim()
const brand = n => execFileSync('node', [tool, 'filled', n], { encoding: 'utf8' }).trim()
// Activity and brand icons the mod already ships (live/icons.json).
const lib = JSON.parse(readFileSync(new URL('../../live/icons.json', import.meta.url), 'utf8'))
const icons = {
  progress: central('IconProgress50'), chev: central('IconChevronRightSmall'), dchev: central('IconChevronDownSmall'),
  grabber: central('IconChevronGrabberVertical'), star: central('IconStar'), alert: central('IconExclamationCircle'), gauge: central('IconGauge'),
  m_claude: brand('IconClaudeai'), m_openai: brand('IconOpenai'), m_gemini: brand('IconGemini'), m_grok: brand('IconGrok'),
  m_mistral: brand('IconMistral'), m_deepseek: brand('IconDeepseek'), m_meta: brand('IconMetaAi'), m_bot: central('IconAiBotHead'),
  folder: central('IconFolder1'), tup: central('IconThumbsUp'), tdown: central('IconThumbsDown'), up: central('IconArrowUp'), down: central('IconArrowDown'),
  checking: central('IconEyeOpen'), delegating: central('IconArrowSplitRight'), asking: central('IconBubbleQuestion'),
  settings: central('IconSettingsSliderThree'), hide: central('IconCrossSmall'),
  task_ok: roundFilled('IconCircleCheck'), task_fail: roundFilled('IconCircleX'),
}
for (const k of ['thinking', 'researching', 'designing', 'building', 'running', 'done', 'save', 'check', 'figma', 'github', 'notion', 'linear', 'google', 'chrome', 'plugin']) icons[k] = lib[k]
const out = {}
for (const [k, svg] of Object.entries(icons)) {
  const vb = /viewBox="([^"]+)"/.exec(svg)?.[1] ?? '0 0 24 24'
  out[k] = { viewBox: vb, inner: svg.replace(/^[\s\S]*?<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '') }
}
writeFileSync(new URL('../src/icons/svgs.ts', import.meta.url),
  '// Generated by scripts/gen-icons.mjs from Central Icons. Do not edit by hand.\n' +
  `export const SVGS = ${JSON.stringify(out, null, 1)} as const\nexport type IconName = keyof typeof SVGS\n`)
console.log('icons', Object.keys(out).length)
